INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Systemprüfung immer automatisch läuft?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Checks möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft mir, ein Netzwerk auf Schwachstellen zu überprüfen?', 3, '[{"text": "Nessus", "correct": true, "because": "Scant Schwachstellen"}, {"text": "Notepad", "correct": false, "because": "Nur Text"}, {"text": "Browser", "correct": false, "because": "Kein Sicherheitswerkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei einer Systemüberprüfung wichtig?', 5, '[{"text": "Monitoring", "correct": true, "because": "Erkennt Anomalien"}, {"text": "Protokollanalyse", "correct": true, "because": "Findet Fehler"}, {"text": "Sicherheitsprüfung", "correct": true, "because": "Schützt System"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Regelmäßige Checks finden Schwachstellen. b) Einmalige Prüfung reicht aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk überprüfe?', 4, '[{"text": "Protokolldaten", "correct": false, "because": "Zeigen Probleme"}, {"text": "Firewall-Regeln", "correct": false, "because": "Wichtig für Sicherheit"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Überprüfung immer manuell sein muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierung möglich"}, {"text": "Ja", "correct": false, "because": "Tools helfen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Software auf Fehler zu testen?', 3, '[{"text": "Unit-Tests", "correct": true, "because": "Prüfen Funktionen"}, {"text": "Designanpassung", "correct": false, "because": "Kein Test"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine regelmäßige Systemprüfung?', 5, '[{"text": "Früherkennung", "correct": true, "because": "Findet Probleme früh"}, {"text": "Sicherheitsverbesserung", "correct": true, "because": "Schließt Lücken"}, {"text": "Leistungssteigerung", "correct": true, "because": "Optimiert System"}, {"text": "Farbauswahl", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Logs bei der Überprüfung helfen und b) einmalige Checks ausreichen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein System zu überprüfen?', 4, '[{"text": "Monitoring-Tools", "correct": false, "because": "Erkennen Probleme"}, {"text": "Protokolle", "correct": false, "because": "Dokumentieren Fehler"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ich ein Netzwerk täglich prüfen?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Risiko"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken helfen bei einer Systemprüfung?', 4, '[{"text": "Penetrationstests", "correct": true, "because": "Finden Schwachstellen"}, {"text": "Log-Analyse", "correct": true, "because": "Erkennt Anomalien"}, {"text": "Farbanpassung", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Überprüfungen nur Hardware betreffen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software"}, {"text": "Ja", "correct": false, "because": "Umfassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer regelmäßigen Überprüfung?', 3, '[{"text": "Sicherheitslücken schließen", "correct": true, "because": "Schützt System"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}, {"text": "Kosten erhöhen", "correct": false, "because": "Nicht Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Monitoring erkennt Probleme früh. b) Audits sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Audits oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Protokollanalyse?', 4, '[{"text": "Fehlerursachen finden", "correct": true, "because": "Dokumentiert Ereignisse"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Überprüfung immer physisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch remote möglich"}, {"text": "Ja", "correct": false, "because": "Tools nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Überprüfung effektiv?', 5, '[{"text": "Regelmäßigkeit", "correct": true, "because": "Hält System sicher"}, {"text": "Tools", "correct": true, "because": "Automatisieren"}, {"text": "Dokumentation", "correct": true, "because": "Nachverfolgbarkeit"}, {"text": "Büroverschönerung", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erkennt ein Audit auch zukünftige Probleme?', 3, '[{"text": "Nein", "correct": true, "because": "Nur aktuelle Schwachstellen"}, {"text": "Ja", "correct": false, "because": "Analyse aktueller Zustand"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer Systemprüfung?', 4, '[{"text": "Netzwerkausfall analysieren", "correct": true, "because": "Findet Ursachen"}, {"text": "Software designen", "correct": false, "because": "Kein Check"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}]');
